'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),E=require('./flow');
const root=path.resolve(__dirname,'..'),out=process.env.NARUTO_EDITOR_TEST_OUT||path.join(root,'evidence/editor_v021'),rom=fs.readFileSync(path.join(root,'originals/naruto_konoha_bearteam_simp.gba')),sample=fs.readFileSync(path.join(root,'build/naruto_fog_harbor_sample_v0.2.0.gba')),hash=b=>crypto.createHash('sha256').update(b).digest('hex'),checks=[],fresh=()=>new E.Editor(rom),font=()=>new Uint8Array(32).fill(255);
const test=(name,fn)=>{fn();checks.push({name,result:'pass'});console.log('PASS',name);};
test('user-confirmed 8959 and surrounding characters decode without a global shift',()=>{const m=fresh();assert.equal(m.mapping[0x8959],'焙');assert.equal(m.mapping[0x895a],'被');assert.equal(m.mapping[0x8957],'备');assert.equal(m.mapping[0x897e],'边');assert.equal(m.mapping[0x8a40],'尝');assert(!m.mapping[0x8a7f]);assert(m.textValue(m.dialogues(1)[1]).includes('准备'));});
test('font fingerprint prevents applying inferred labels to changed graphics',()=>{const b=Buffer.from(rom);b[0xa3074]^=3;const m=new E.Editor(b);assert.equal(m.mapping[0x8959],undefined);});
test('both originals and exported example stay byte-identical without edits',()=>{for(const bytes of[rom,sample])assert.equal(hash(new E.Editor(bytes).build(font)),hash(bytes));});
test('all sixty portraits decode within bounds and Lee matches native piece layout',()=>{const m=fresh();for(let id=1;id<=60;id++){const p=m.renderPortrait(id);assert.equal(p.pixels.length,80*80*4);assert(p.pixels.some(v=>v));}assert.equal(m.renderPortrait(12).pixels.filter((v,i)=>i%4===3&&v).length,4139);assert(m.renderPortrait(36).placeholder);});
test('same-text speaker change preserves every native text byte',()=>{const m=fresh(),e=m.dialogues(1).find(e=>e.op===1&&e.length>=5),native=rom.slice(e.text.start,e.text.end);m.setText(e,m.textValue(e),12);const b=m.build(font),dest=E.u32(b,e.offset+1)-E.BASE;assert.deepEqual(b.slice(dest+7,dest+7+native.length),new Uint8Array(native));});
test('one-word edit retains all unchanged native glyph bytes',()=>{const m=fresh(),e=m.dialogues(1)[1],value=m.textValue(e),native=rom.slice(e.text.start,e.text.end);m.setText(e,'A'+value);const b=m.build(font),dest=E.u32(b,e.offset+1)-E.BASE;assert.equal(b[dest+1],65);assert.deepEqual(b.slice(dest+2,dest+2+native.length),new Uint8Array(native));});
test('manual corrections undo, validate, save, load and reopen',()=>{const m=fresh();m.transaction('correction',()=>m.setGlyphLabel(0x9875,'咳'));assert.equal(m.mapping[0x9875],'咳');const proj=m.project(hash(rom)),q=fresh();q.importProject(proj,hash(rom));assert.equal(q.mapping[0x9875],'咳');const b=q.build(font),again=new E.Editor(b);assert.equal(again.mapping[0x9875],'咳');assert.equal(hash(again.build(font)),hash(b));m.undo();assert.equal(m.mapping[0x9875],fresh().mapping[0x9875]);assert.equal(hash(m.build(font)),hash(rom));assert.throws(()=>m.setGlyphLabel(0xffff,'咳'));assert.throws(()=>m.setGlyphLabel(0x9875,'两个'));});
test('glyph correction on an event ROM appends labels without rewriting existing bytes',()=>{const m=new E.Editor(sample);m.setGlyphLabel(0x9875,'咳');const b=m.build(font);assert.deepEqual(b.slice(0,sample.length),new Uint8Array(sample));});
test('bad imported glyph correction rolls back all associated edits',()=>{const m=fresh(),p=m.project(hash(rom));p.features.glyphCorrections={65535:'错'};assert.throws(()=>m.importProject(p,hash(rom)));assert.equal(hash(m.build(font)),hash(rom));});
test('flow starts with actual original prologue and sample begins at rewritten first mission',()=>{const m=fresh(),original=m.flowItems(),modified=new E.Editor(sample).flowItems();assert.equal(original[0].scene,54);assert.equal(modified[0].scene,1);assert(modified[0].title.includes('雾港信标'));assert(original.some(x=>x.scene===40&&x.kind==='battle'));assert(original.filter(x=>x.scene===50).length>5);assert(original.filter(x=>x.group==='主线流程').every(x=>x.scene<32||x.scene>38));});
test('each story navigation row resolves real dialogue and distinct shared-location branches',()=>{const m=fresh(),items=m.flowItems();for(const x of items)if(x.kind==='story')assert(m.dialogueSequence(x.scene,x).length>0,x.title);const a=items.find(x=>x.scene===50&&x.progress===0),b=items.find(x=>x.scene===50&&x.progress===45),ta=m.dialogueSequence(50,a),tb=m.dialogueSequence(50,b);assert.notEqual(ta[0].key,tb[0].key);assert(m.textValue(ta[1]).includes('鸣人'));assert.equal(m.dialogueSequence(54,items[0])[1].speaker,1);assert(m.textValue(m.dialogueSequence(1)[0]).includes('出发'));assert(m.textValue(m.dialogueSequence(1)[1]).includes('准备'));});
test('every battlefield remains reachable in both original and modified catalogues',()=>{for(const bytes of[rom,sample]){const m=new E.Editor(bytes),stages=new Set(m.flowItems().filter(x=>x.kind==='battle'||x.kind==='branch').map(x=>x.scene));assert.equal(stages.size,46);}});
test('Chinese facing labels agree with actual native movement previews',()=>{const report=JSON.parse(fs.readFileSync(path.join(root,'evidence/editor_v021/facing_moves/report.json')));for(const row of report.values)assert.equal(new Map(E.directions).get(row.preview),row.direction);});
fs.writeFileSync(path.join(out,'catalog_tests.json'),JSON.stringify({result:'pass',kind:'static catalogue, ROM preservation and project tests; direction enum compared with actual-key snapshot evidence',checks},null,2));console.log(checks.length,'catalogue checks passed');
